const C = dark
  ? ['#3987e5', '#d95926', '#199e70', '#c98500', '#d55181']
  : ['#2a78d6', '#eb6834', '#1baf7a', '#eda100', '#e87ba4'];
const GOOD = '#0ca30c', CRIT = '#d03b3b';
const echarts = context.echarts;
const frames = context.panel.data.series || [];
const num = (s) => s.fields.find((f) => f.type === 'number');
const tim = (s) => s.fields.find((f) => f.type === 'time');
const lab = (s) => (num(s) && num(s).labels) || {};
const last = (s) => { const v = Array.from(num(s).values); return v.length ? v[v.length - 1] : null; };
const pts = (s) => { const t = Array.from(tim(s).values), v = Array.from(num(s).values); return t.map((x, i) => [x, v[i]]); };
const bps = (b) => { const a = Math.abs(b || 0); return a >= 1e9 ? (a / 1e9).toFixed(2) + ' Gb/s' : a >= 1e6 ? (a / 1e6).toFixed(1) + ' Mb/s' : a >= 1e3 ? (a / 1e3).toFixed(0) + ' kb/s' : a.toFixed(0) + ' b/s'; };
const tip = {
  backgroundColor: dark ? 'rgba(24,27,31,0.96)' : 'rgba(255,255,255,0.98)',
  borderColor: dark ? 'rgba(255,255,255,0.10)' : 'rgba(11,11,11,0.10)',
  textStyle: { color: ink.p, fontSize: 12 },
  extraCssText: 'border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,.35);',
};
const base = { backgroundColor: 'transparent', textStyle: { fontFamily: 'Inter, Helvetica, Arial, sans-serif', color: ink.s }, animationDuration: 900, animationEasing: 'cubicOut' };

const grad = (c) => new echarts.graphic.LinearGradient(0, 0, 0, 1, [{ offset: 0, color: c + '66' }, { offset: 1, color: c + '00' }]);
const card = ({ label, color, value, unit, valueColor, sub, spark, fmt, strip, pulse }) => {
  const g = [
    { type: 'circle', left: 16, top: 19, z: 10, shape: { r: 4 }, style: { fill: color } },
    { type: 'text', left: 28, top: 14, z: 10, style: { text: label.toUpperCase(), fill: ink.m, font: '600 11px Inter, Helvetica, sans-serif' } },
    { type: 'text', left: 16, top: 36, z: 10, style: { text: `{v|${value}}{u|${unit ? ' ' + unit : ''}}`,
      rich: { v: { fill: valueColor || ink.p, font: '600 30px Inter, Helvetica, sans-serif' }, u: { fill: ink.s, font: '500 14px Inter, Helvetica, sans-serif', padding: [8, 0, 0, 2] } } } },
    { type: 'text', left: 16, top: 78, z: 10, style: { text: sub, fill: ink.m, font: '12px Inter, Helvetica, sans-serif' } },
  ];
  if (pulse) {
    g.push({ type: 'circle', right: 22, top: 18, z: 10, shape: { r: 5 }, style: { fill: color } });
    g.push({ type: 'circle', right: 22, top: 18, z: 9, shape: { r: 5 }, style: { fill: color, opacity: 0.5 },
      keyframeAnimation: { duration: 1800, loop: true, keyframes: [
        { percent: 0, scaleX: 1, scaleY: 1, style: { opacity: 0.55 } }, { percent: 1, scaleX: 3.2, scaleY: 3.2, style: { opacity: 0 } }] },
      originX: 5, originY: 5 });
  }
  const series = [];
  if (spark && spark.length) {
    if (strip) {
      const band = (c, keep) => ({ type: 'line', step: 'end', showSymbol: false, lineStyle: { width: 0 }, areaStyle: { color: c, opacity: 0.9 },
        data: spark.map(([t, v]) => [t, keep(v) ? 1 : 0]) });
      series.push(band(GOOD, (v) => v >= 0.5), band(CRIT, (v) => v < 0.5));
    } else series.push({ type: 'line', data: spark, smooth: 0.4, showSymbol: false, symbolSize: 8, lineStyle: { width: 2, color, cap: 'round' },
          itemStyle: { color, borderColor: ink.surf, borderWidth: 2 }, areaStyle: { color: grad(color) } });
  }
  return {
    ...base, graphic: g, series,
    grid: strip ? { left: 16, right: 16, bottom: 14, height: 10 } : { left: 0, right: 0, bottom: 0, height: '36%' },
    xAxis: { type: 'time', show: false }, yAxis: { type: 'value', show: false, scale: !strip, min: strip ? 0 : null, max: strip ? 1 : null },
    tooltip: { ...tip, trigger: 'axis', axisPointer: { type: 'line', lineStyle: { color: ink.m, type: 'dashed' } },
      formatter: (ps) => { const p0 = strip ? (ps.find((x) => x.value[1] === 1) || ps[0]) : ps[0]; const v = strip ? (p0.seriesIndex === 0 ? 1 : 0) : p0.value[1]; return `<div style="color:${ink.m}">${new Date(p0.value[0]).toLocaleString()}</div><b>${fmt ? fmt(v) : v}</b>`; } },
  };
};
const ser = (ref) => frames.find((x) => x.refId === ref);
const lastOf = (ref) => { const x = ser(ref); return x ? last(x) : null; };
const ptsOf = (ref) => { const x = ser(ref); return x && tim(x) ? pts(x) : []; };

