const v = (t, d) => { const s = frames.find((x) => lab(x).error_type === t && lab(x).network_io_direction === d); return s ? Math.round(last(s) || 0) : 0; };
const rx = types.map((t) => v(t, 'receive')), tx = types.map((t) => v(t, 'transmit'));
const total = [...rx, ...tx].reduce((a, b) => a + b, 0);
const bar = (name, data, c) => ({ name, type: 'bar', data, barMaxWidth: 28, itemStyle: { color: c, borderRadius: [4, 4, 0, 0] },
  label: { show: true, position: 'top', color: ink.s, fontSize: 11, formatter: (p) => p.value ? p.value.toLocaleString() : '' } });
return {
  ...base,
  legend: { top: 0, right: 8, icon: 'roundRect', itemWidth: 12, itemHeight: 4, textStyle: { color: ink.s } },
  grid: { left: 48, right: 16, top: 36, bottom: 28 },
  tooltip: { ...tip, trigger: 'axis', axisPointer: { type: 'shadow', shadowStyle: { color: ink.grid, opacity: 0.4 } } },
  xAxis: { type: 'category', data: types.map((t) => t.toUpperCase()), axisLine: { lineStyle: { color: ink.base } }, axisTick: { show: false }, axisLabel: { color: ink.s } },
  yAxis: { type: 'value', minInterval: 1, axisLabel: { color: ink.m }, splitLine: { lineStyle: { color: ink.grid } } },
  graphic: total === 0 ? [{ type: 'text', left: 'center', top: '42%', style: { text: 'No line errors in this time range', fill: GOOD, fontSize: 14, fontWeight: 600 } }] : [],
  series: [bar('Downstream', rx, C[0]), bar('Upstream', tx, C[1])],
};

const T = context.grafana && context.grafana.theme;
const dark = T ? T.isDark : true;
const ink = dark
  ? { p: '#ffffff', s: '#c3c2b7', m: '#898781', grid: '#2c2c2a', base: '#383835', surf: '#181b1f' }
  : { p: '#0b0b0b', s: '#52514e', m: '#898781', grid: '#e1e0d9', base: '#c3c2b7', surf: '#ffffff' };
const C = dark
  ? ['#3987e5', '#d95926', '#199e70', '#c98500', '#d55181']
  : ['#2a78d6', '#eb6834', '#1baf7a', '#eda100', '#e87ba4'];
const GOOD = '#0ca30c', CRIT = '#d03b3b';
const echarts = context.echarts;
const frames = context.panel.data.series || [];
const num = (s) => s.fields.find((f) => f.type === 'number');
const tim = (s) => s.fields.find((f) => f.type === 'time');
const lab = (s) => (num(s) && num(s).labels) || {};
const last = (s) => { const v = Array.from(num(s).values); return v.length ? v[v.length - 1] : null; };
const pts = (s) => { const t = Array.from(tim(s).values), v = Array.from(num(s).values); return t.map((x, i) => [x, v[i]]); };
const bps = (b) => { const a = Math.abs(b || 0); return a >= 1e9 ? (a / 1e9).toFixed(2) + ' Gb/s' : a >= 1e6 ? (a / 1e6).toFixed(1) + ' Mb/s' : a >= 1e3 ? (a / 1e3).toFixed(0) + ' kb/s' : a.toFixed(0) + ' b/s'; };
const tip = {
  backgroundColor: dark ? 'rgba(24,27,31,0.96)' : 'rgba(255,255,255,0.98)',
  borderColor: dark ? 'rgba(255,255,255,0.10)' : 'rgba(11,11,11,0.10)',
  textStyle: { color: ink.p, fontSize: 12 },
  extraCssText: 'border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,.35);',
};
const base = { backgroundColor: 'transparent', textStyle: { fontFamily: 'Inter, Helvetica, Arial, sans-serif', color: ink.s }, animationDuration: 900, animationEasing: 'cubicOut' };

const pick = (ref, d) => frames.find((s) => s.refId === ref && lab(s).network_io_direction === d);
const series = [['Downstream', 'receive', C[0]], ['Upstream', 'transmit', C[1]]].map(([name, d, c]) => {
  const s = pick('A', d);
  return { name, type: 'line', data: s ? pts(s) : [], smooth: 0.3, showSymbol: false, symbolSize: 8,
    lineStyle: { width: 2, color: c, cap: 'round' }, itemStyle: { color: c, borderColor: ink.surf, borderWidth: 2 },
    endLabel: { show: true, color: ink.s, fontSize: 11, formatter: (p) => `${p.value[1].toFixed(1)} dB` } };
});
series[0].markArea = { silent: true, itemStyle: { color: CRIT, opacity: 0.12 },
  label: { color: CRIT, fontSize: 11, position: 'insideTopLeft' }, data: [[{ yAxis: 0, name: 'low margin (< 6 dB)' }, { yAxis: 6 }]] };
const att = (d) => { const s = pick('B', d); return s ? (last(s) || 0).toFixed(1) : '-'; };
return {
  ...base,
  title: { text: `Attenuation  down ${att('receive')} dB  ·  up ${att('transmit')} dB`, left: 8, top: 0, textStyle: { fontSize: 12, fontWeight: 500, color: ink.m } },
  legend: { top: 0, right: 8, icon: 'roundRect', itemWidth: 12, itemHeight: 4, textStyle: { color: ink.s } },
  grid: { left: 48, right: 64, top: 36, bottom: 28 },
  tooltip: { ...tip, trigger: 'axis', valueFormatter: (v) => `${(+v).toFixed(1)} dB` },
  xAxis: { type: 'time', axisLine: { lineStyle: { color: ink.base } }, axisTick: { show: false }, axisLabel: { color: ink.m, hideOverlap: true } },
  yAxis: { type: 'value', min: 0, axisLabel: { color: ink.m, formatter: '{value} dB' }, splitLine: { lineStyle: { color: ink.grid } } },
  series,
};

const T = context.grafana && context.grafana.theme;
const dark = T ? T.isDark : true;
const ink = dark
  ? { p: '#ffffff', s: '#c3c2b7', m: '#898781', grid: '#2c2c2a', base: '#383835', surf: '#181b1f' }
  : { p: '#0b0b0b', s: '#52514e', m: '#898781', grid: '#e1e0d9', base: '#c3c2b7', surf: '#ffffff' };
const C = dark
  ? ['#3987e5', '#d95926', '#199e70', '#c98500', '#d55181']
  : ['#2a78d6', '#eb6834', '#1baf7a', '#eda100', '#e87ba4'];
const GOOD = '#0ca30c', CRIT = '#d03b3b';
const echarts = context.echarts;
const frames = context.panel.data.series || [];
const num = (s) => s.fields.find((f) => f.type === 'number');
const tim = (s) => s.fields.find((f) => f.type === 'time');
const lab = (s) => (num(s) && num(s).labels) || {};
const last = (s) => { const v = Array.from(num(s).values); return v.length ? v[v.length - 1] : null; };
const pts = (s) => { const t = Array.from(tim(s).values), v = Array.from(num(s).values); return t.map((x, i) => [x, v[i]]); };
const bps = (b) => { const a = Math.abs(b || 0); return a >= 1e9 ? (a / 1e9).toFixed(2) + ' Gb/s' : a >= 1e6 ? (a / 1e6).toFixed(1) + ' Mb/s' : a >= 1e3 ? (a / 1e3).toFixed(0) + ' kb/s' : a.toFixed(0) + ' b/s'; };
const tip = {
  backgroundColor: dark ? 'rgba(24,27,31,0.96)' : 'rgba(255,255,255,0.98)',
  borderColor: dark ? 'rgba(255,255,255,0.10)' : 'rgba(11,11,11,0.10)',
  textStyle: { color: ink.p, fontSize: 12 },
  extraCssText: 'border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,.35);',
};
const base = { backgroundColor: 'transparent', textStyle: { fontFamily: 'Inter, Helvetica, Arial, sans-serif', color: ink.s }, animationDuration: 900, animationEasing: 'cubicOut' };

const s = frames[0];
const data = s ? pts(s) : [];
const now = data.length ? data[data.length - 1][1] : 0;
return {
  ...base,
  title: { text: `${(now || 0).toFixed(1)}%`, subtext: 'of downstream link speed now', left: 8, top: 0,
    textStyle: { fontSize: 22, fontWeight: 600, color: ink.p }, subtextStyle: { fontSize: 11, color: ink.m }, itemGap: 2 },
  grid: { left: 48, right: 20, top: 56, bottom: 28 },
  tooltip: { ...tip, trigger: 'axis', valueFormatter: (v) => `${(+v).toFixed(2)}%` },
  xAxis: { type: 'time', axisLine: { lineStyle: { color: ink.base } }, axisTick: { show: false }, axisLabel: { color: ink.m, hideOverlap: true } },
  yAxis: { type: 'value', min: 0, max: (v) => Math.max(10, Math.ceil(v.max / 10) * 10), axisLabel: { color: ink.m, formatter: '{value}%' }, splitLine: { lineStyle: { color: ink.grid } } },
  visualMap: { show: false, type: 'continuous', dimension: 1, min: 0, max: 100, inRange: { color: dark ? ['#5f9ee9', '#1d5aa8'] : ['#8ab6ec', '#1d5aa8'] } },
  series: [{ name: 'Utilization', type: 'line', data, smooth: 0.35, showSymbol: false, lineStyle: { width: 2 },
    areaStyle: { opacity: 0.18 },
    markLine: { silent: true, symbol: 'none', lineStyle: { color: CRIT, type: 'dashed', width: 1 },
      label: { color: CRIT, fontSize: 11, formatter: 'saturated 80%' }, data: [{ yAxis: 80 }] } }],
};
